Process_Node* process_create( UInt8 *name ) 
{
    Process_Node *process = NULL ;

    process_init();
    
    process = (Process_Node *)os_mem_request( sizeof ( *process ) );    

    if( process )
    {
        process->name = name  ; 
    }

    return process ; 
}

